def minimum_columns_for_rowwise_order(strs):
 m=len(strs[0]);dp=[1]*m
 for j in range(m):
  for i in range(j):
   if all(row[i]<=row[j] for row in strs):dp[j]=max(dp[j],dp[i]+1)
 return m-max(dp)

